//! Every AI label supplies one entry for every supported interface language.
use crate::Language;
macro_rules! catalog {
    ($($name:ident => [$($text:literal),+]),+ $(,)?) => {
        #[derive(Debug,Clone,Copy,PartialEq,Eq)] #[repr(usize)] pub enum AiMsg {$($name),+}
        impl AiMsg {pub const ALL:&'static [Self]=&[$(Self::$name),+];}
        pub fn ai_t(language:Language,message:AiMsg)->&'static str {
            const LABELS:&[[&str;7]]=&[$([$($text),+]),+];
            let index=match language {Language::En=>0,Language::ZhHans=>1,Language::ZhHant=>2,Language::Ja=>3,Language::Fr=>4,Language::De=>5,Language::Es=>6};LABELS[message as usize][index]
        }
    }
}
