pub fn ai_error(language: Language, error: markion_ai::AiError) -> &'static str {
    use markion_ai::AiError;
    ai_t(
        language,
        match error {
            AiError::Disabled => AiMsg::Disabled,
            AiError::InvalidProfile => AiMsg::Invalid,
            AiError::MissingKey => AiMsg::MissingKey,
            AiError::Authentication => AiMsg::Auth,
            AiError::NotFound => AiMsg::NotFound,
            AiError::RateLimited => AiMsg::RateLimit,
            AiError::Unavailable => AiMsg::Unavailable,
            AiError::Timeout => AiMsg::Timeout,
            AiError::Canceled => AiMsg::Canceled,
            AiError::Unsupported => AiMsg::Unsupported,
            AiError::Protocol => AiMsg::ProtocolError,
            AiError::Limit => AiMsg::OverBudget,
            AiError::Scope => AiMsg::ScopeError,
            AiError::Stale => AiMsg::Stale,
        },
    )
}
pub fn writing_label(action: markion_ai::writing::WritingAction) -> AiMsg {
    use markion_ai::writing::WritingAction as W;
    match action {
        W::Draft => AiMsg::Draft,
        W::Continue => AiMsg::Continue,
        W::Polish => AiMsg::Polish,
        W::Correct => AiMsg::Correct,
        W::Shorten => AiMsg::Shorten,
        W::Expand => AiMsg::Expand,
        W::Tone => AiMsg::Tone,
        W::Translate => AiMsg::Translate,
        W::Summarize => AiMsg::Summarize,
        W::Outline => AiMsg::Outline,
        W::Tasks => AiMsg::Tasks,
        W::Custom => AiMsg::CustomWriting,
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn complete_for_every_language() {
        for &language in Language::all() {
            for &message in AiMsg::ALL {
                assert!(!ai_t(language, message).is_empty());
            }
        }
    }
}
